'use strict';
const shareToken=location.hash.slice(1),shareGate=document.querySelector('#share-gate'),shareMessage=document.querySelector('#share-message'),shareForm=document.querySelector('#share-password-form'),shareFrame=document.querySelector('#shared-report'),sharePrint=document.querySelector('#share-print');let shareExpires=0;
function closeSharedReport(message){shareFrame.hidden=true;shareFrame.removeAttribute('srcdoc');shareGate.hidden=false;shareMessage.textContent=message;shareForm.hidden=true;sharePrint.hidden=true;document.querySelector('#share-password').value='';}
async function fetchSharedReport(password){const owner=/^owner=[a-f0-9-]{36}$/.test(shareToken);if(!owner&&!/^[a-f0-9]{64}$/.test(shareToken))return closeSharedReport('Liên kết không hợp lệ. Hãy kiểm tra lại link được chia sẻ.');try{const response=await fetch(owner?'/api/report-shares?id='+shareToken.slice(6):'/api/report-share/'+shareToken,{method:password===undefined?'GET':'POST',headers:password===undefined?{}:{'Content-Type':'application/json'},body:password===undefined?undefined:JSON.stringify({password}),credentials:owner?'same-origin':'omit',cache:'no-store',referrerPolicy:'no-referrer'});const data=await response.json();if(!response.ok){if(response.status===401){shareMessage.textContent=data.error;return;}return closeSharedReport(data.error||'Chưa mở được báo cáo.');}shareExpires=data.expires;document.querySelector('#share-expiry').textContent='Hết hạn: '+new Date(data.expires).toLocaleString('vi-VN',{timeZone:'Asia/Ho_Chi_Minh'})+' (VN)';if(data.locked){shareGate.hidden=false;shareForm.hidden=false;shareMessage.textContent='Nhập mật khẩu do người chia sẻ cung cấp để xem báo cáo.';return;}shareGate.hidden=true;shareForm.hidden=true;shareFrame.srcdoc=data.html;shareFrame.hidden=false;shareFrame.onload=()=>{refineSharedReport();if(Date.now()<shareExpires)sharePrint.hidden=false;};document.title=data.title||'Báo cáo tuần · Zen Studio';}catch{shareGate.hidden=false;shareMessage.textContent='Chưa kết nối được máy chủ. Tải lại trang để thử lại.';}}
shareForm.onsubmit=async e=>{e.preventDefault();const button=shareForm.querySelector('button');button.disabled=true;try{await fetchSharedReport(document.querySelector('#share-password').value);}finally{document.querySelector('#share-password').value='';button.disabled=false;}};
sharePrint.onclick=()=>{if(Date.now()>=shareExpires)return closeSharedReport('Liên kết đã hết hạn.');shareFrame.contentWindow.focus();shareFrame.contentWindow.print();};setInterval(()=>{if(shareExpires&&Date.now()>=shareExpires)closeSharedReport('Liên kết đã hết hạn. Liên hệ người chia sẻ để nhận link mới.');},1000);fetchSharedReport();

function refineSharedReport(){const d=shareFrame.contentDocument;if(!d)return;const style=d.createElement('style');style.textContent='.report-sheet{max-width:900px!important;border-radius:18px;margin:20px auto!important;padding:28px!important}.report-distribution{margin:18px 0 32px;background:#faf8fc;border:1px solid #eee8f3;border-collapse:separate!important;border-spacing:0;border-radius:12px;overflow:hidden}.report-distribution tr:nth-child(even){display:none}.report-distribution td{padding:12px 16px!important;border-bottom:1px solid #eee8f3}.report-donut circle[stroke-dasharray]{pointer-events:stroke;transition:stroke-width .2s,filter .2s;cursor:help}.report-donut circle[stroke-dasharray]:hover,.report-donut circle[stroke-dasharray]:focus{stroke-width:32;filter:brightness(1.08)}.report-hover-info{font-size:13px;text-align:center;min-height:24px;color:#665078;margin:0 0 14px}@media print{.report-sheet{margin:0!important;padding:0!important}.report-hover-info{display:none}}';d.head.append(style);const rows=[...d.querySelectorAll('.report-distribution tr')].filter(r=>r.cells.length===2),labels=rows.map(r=>r.textContent.trim()),circles=[...d.querySelectorAll('.report-donut circle[stroke-dasharray]')],info=d.createElement('p');info.className='report-hover-info';info.textContent='Rê chuột hoặc chạm từng phần màu để xem số lượng và tỷ lệ.';d.querySelector('.report-donut')?.after(info);circles.forEach(c=>{const color=c.getAttribute('stroke'),row=rows.find(r=>r.querySelector('span')?.getAttribute('style')?.includes(color)),label=row?.textContent.trim()||'Phân bố công việc';c.setAttribute('tabindex','0');c.setAttribute('aria-label',label);const title=d.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=label;c.append(title);for(const event of ['pointerenter','focus','click'])c.addEventListener(event,()=>{info.textContent=label;});});}
